"""Migration of the Meridian CRM division-by-zero behavior."""


def _legacy_number(value: object) -> float:
    """Coerce a value using the legacy numeric rules."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        if value.strip() == "":
            return 0.0

    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        # Preserve the non-raising legacy behavior for values that cannot
        # otherwise be converted in numeric context.
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy coercion and division-by-zero semantics."""
    numerator = _legacy_number(a)
    denominator = _legacy_number(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return float(numerator / denominator), []
    except (ArithmeticError, OverflowError):
        return 0.0, ["SCRIPT_DIV0"]
